function opts(g:string,vals:string[],cur:string){return `<div class="variant-grid">${vals.map(v=>`<button class="variant ${v===cur?'active':''}" data-g="${g}" data-v="${v}">${v}</button>`).join('')}</div>`}
function edibleStyles(size:string){return ['4 inch','4.5 inch','5 inch','5.5 inch'].includes(size)?['Round / Bulat','Square / Petak','Love Shape / Hati','Custom']:P.edible.style}
function simpleFourVariant(now:boolean,k:Extract<K,'edible'|'wafer'>){const p=P[k],reviews=['No Review','Need Review'];let process=p.process[0],review=reviews[0],size=p.size[0],style=edibleStyles(size)[0],qty=1;const w=modal(`<button class="modal-x">×</button><div class="variant-head">${photo(k)}<div><strong id="vprice">${money(price(k,process,size,style,review))}</strong><span>Stock tersedia</span></div></div><section class="variant-body"><h3>Process</h3>${opts('process',p.process,process)}${processNote}<h3>Review</h3>${opts('review',reviews,review)}<h3>Size</h3>${opts('size',p.size,size)}<h3>${k==='wafer'?'Shape':'Shape'}</h3>${opts('style',edibleStyles(size),style)}<div class="qty"><span>Quantity</span><div><button id="minus">−</button><b id="qty">1</b><button id="plus">+</button></div></div></section><button id="confirm" class="confirm">${now?'Buy Now':'Add to Cart'}</button>`);const paint=()=>{const allowed=edibleStyles(size);if(!allowed.includes(style))style=allowed[0];w.querySelector<HTMLElement>('#vprice')!.textContent=money(price(k,process,size,style,review));w.querySelector<HTMLElement>('#qty')!.textContent=String(qty);w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>{const v=b.dataset.g==='process'?process:b.dataset.g==='review'?review:b.dataset.g==='size'?size:style;const disabled=b.dataset.g==='style'&&!allowed.includes(b.dataset.v!);b.disabled=disabled;b.classList.toggle('disabled',disabled);b.classList.toggle('active',!disabled&&b.dataset.v===v)})};w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>b.onclick=()=>{if(b.dataset.g==='process')process=b.dataset.v!;if(b.dataset.g==='review')review=b.dataset.v!;if(b.dataset.g==='size')size=b.dataset.v!;if(b.dataset.g==='style'&&!b.disabled)style=b.dataset.v!;paint()});paint();w.querySelector<HTMLButtonElement>('#minus')!.onclick=()=>{qty=Math.max(1,qty-1);paint()};w.querySelector<HTMLButtonElement>('#plus')!.onclick=()=>{qty++;paint()};w.querySelector<HTMLButtonElement>('#confirm')!.onclick=()=>{const id=`${k}|${process}|${review}|${size}|${style}`,f=cart.find(i=>i.id===id);if(f)f.qty+=qty;else cart.push({id,k,title:p.name,process,review,size,style,price:price(k,process,size,style,review),qty});save();w.remove();if(now)navigate('review');else{render();toast('Ditambah ke cart')}}}
function printedVariant(now:boolean){let name='',theme='Happy Birthday',qty=1;const w=modal(`<button class="modal-x">×</button><div class="variant-head">${photo('printed')}<div><strong>${money(10)}</strong><span>Custom name</span></div></div><section class="variant-body"><label>Nama / Wording<input id="printName" placeholder="Contoh: Happy Birthday Aisyah"></label><label>Tema / Note<input id="printTheme" value="Happy Birthday"></label><div class="qty"><span>Quantity</span><div><button id="minus">−</button><b id="qty">1</b><button id="plus">+</button></div></div></section><button id="confirm" class="confirm">${now?'Buy Now':'Add to Cart'}</button>`);const paint=()=>w.querySelector<HTMLElement>('#qty')!.textContent=String(qty);w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelector<HTMLButtonElement>('#minus')!.onclick=()=>{qty=Math.max(1,qty-1);paint()};w.querySelector<HTMLButtonElement>('#plus')!.onclick=()=>{qty++;paint()};w.querySelector<HTMLButtonElement>('#confirm')!.onclick=()=>{name=(w.querySelector<HTMLInputElement>('#printName')!.value||'Custom Name').trim();theme=w.querySelector<HTMLInputElement>('#printTheme')!.value||'Happy Birthday';cart.push({id:`printed|${Date.now()}`,k:'printed',title:'Cake Topper',process:'Pre-order',review:'Need Review',size:'1 pc',style:theme,customText:name,price:10,qty});save();w.remove();if(now)navigate('review');else{render();toast('Ditambah ke cart')}}}
function burnawayVariant(now:boolean){let process='Pre-order',review='No Review',qty=1;const layers:BurnawayLayers={edible:{size:'5 inch',shape:'Round / Bulat',wording:'',referenceUrl:''},wafer:{size:'5 inch',shape:'Round / Bulat',wording:'',referenceUrl:''}};const layer=(key:keyof BurnawayLayers,label:string,sizes:string[],styles:string[])=>`<h3>${label}</h3><h4>Size</h4>${opts(`${key}-size`,sizes,layers[key].size)}<h4>Shape</h4>${opts(`${key}-shape`,styles,layers[key].shape)}`;const w=modal(`<button class="modal-x">×</button><div class="variant-head">${photo('burnaway')}<div><strong id="vprice">${money(burnawayPrice(layers))}</strong><span>Edible + Wafer (pilih berasingan)</span></div></div><section class="variant-body"><h3>Process</h3>${opts('process',P.burnaway.process,process)}${processNote}<h3>Review</h3>${opts('review',['No Review','Need Review'],review)}${layer('edible','Bottom Layer — Edible Image',P.edible.size.filter(v=>v!=='Cupcake'),P.edible.style)}${layer('wafer','Top Layer — Wafer Paper',P.wafer.size,P.wafer.style)}<div class="qty"><span>Quantity</span><div><button id="minus">−</button><b id="qty">1</b><button id="plus">+</button></div></div></section><button id="confirm" class="confirm">${now?'Buy Now':'Add to Cart'}</button>`);const paint=()=>{w.querySelector<HTMLElement>('#vprice')!.textContent=money(burnawayPrice(layers));w.querySelector<HTMLElement>('#qty')!.textContent=String(qty);w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>{const [key,field]=(b.dataset.g||'').split('-') as [keyof BurnawayLayers,'size'|'shape'];const value=b.dataset.g==='process'?process:b.dataset.g==='review'?review:key&&field?layers[key][field]:'';b.classList.toggle('active',b.dataset.v===value)})};w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>b.onclick=()=>{if(b.dataset.g==='process')process=b.dataset.v!;else if(b.dataset.g==='review')review=b.dataset.v!;else{const [key,field]=(b.dataset.g||'').split('-') as [keyof BurnawayLayers,'size'|'shape'];if(key&&field)layers[key][field]=b.dataset.v!}paint()});paint();w.querySelector<HTMLButtonElement>('#minus')!.onclick=()=>{qty=Math.max(1,qty-1);paint()};w.querySelector<HTMLButtonElement>('#plus')!.onclick=()=>{qty++;paint()};w.querySelector<HTMLButtonElement>('#confirm')!.onclick=()=>{const id=`burnaway|${process}|${review}|${layers.edible.size}|${layers.edible.shape}|${layers.wafer.size}|${layers.wafer.shape}`,f=cart.find(i=>i.id===id),size=`Edible ${layers.edible.size} • Wafer ${layers.wafer.size}`,style=`Edible ${layers.edible.shape} • Wafer ${layers.wafer.shape}`;if(f)f.qty+=qty;else cart.push({id,k:'burnaway',title:P.burnaway.name,process,review,size,style,price:burnawayPrice(layers),qty,customization:{layers:structuredClone(layers)}});save();w.remove();if(now)navigate('review');else{render();toast('Ditambah ke cart')}}}
function variant(now:boolean){if(product==='burnaway'){burnawayVariant(now);return}if(product==='edible'||product==='wafer'){simpleFourVariant(now,product);return}if(product==='printed'){printedVariant(now);return}const p=P[product],reviews=['No Review','Need Review'];let process=p.process[0],review=reviews[0],size=p.size[0],style=p.style[0],qty=1;const w=modal(`<button class="modal-x">×</button><div class="variant-head">${photo(product)}<div><strong id="vprice">${money(price(product,process,size,style))}</strong><span>Stock tersedia</span></div></div><section class="variant-body"><h3>Process</h3>${opts('process',p.process,process)}${processNote}<h3>Review</h3>${opts('review',reviews,review)}<h3>Size</h3>${opts('size',p.size,size)}<h3>Shape / Color</h3>${opts('style',p.style,style)}<div class="qty"><span>Quantity</span><div><button id="minus">−</button><b id="qty">1</b><button id="plus">+</button></div></div></section><button id="confirm" class="confirm">${now?'Buy Now':'Add to Cart'}</button>`);const paint=()=>{const allowed=product==='edible'?edibleStyles(size):p.style;if(!allowed.includes(style))style=allowed[0];w.querySelector<HTMLElement>('#vprice')!.textContent=money(price(product,process,size,style));w.querySelector<HTMLElement>('#qty')!.textContent=String(qty);w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>{const v=b.dataset.g==='process'?process:b.dataset.g==='review'?review:b.dataset.g==='size'?size:style;const disabled=b.dataset.g==='style'&&!allowed.includes(b.dataset.v!);b.disabled=disabled;b.classList.toggle('disabled',disabled);b.classList.toggle('active',!disabled&&b.dataset.v===v)})};w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelectorAll<HTMLButtonElement>('.variant').forEach(b=>b.onclick=()=>{if(b.dataset.g==='process')process=b.dataset.v!;if(b.dataset.g==='review')review=b.dataset.v!;if(b.dataset.g==='size')size=b.dataset.v!;if(b.dataset.g==='style'&&!b.disabled)style=b.dataset.v!;paint()});paint();w.querySelector<HTMLButtonElement>('#minus')!.onclick=()=>{qty=Math.max(1,qty-1);paint()};w.querySelector<HTMLButtonElement>('#plus')!.onclick=()=>{qty++;paint()};w.querySelector<HTMLButtonElement>('#confirm')!.onclick=()=>{const id=`${product}|${process}|${review}|${size}|${style}`,f=cart.find(i=>i.id===id);if(f)f.qty+=qty;else cart.push({id,k:product,title:p.name,process,review,size,style,price:price(product,process,size,style,review),qty});save();w.remove();if(now)navigate('review');else{render();toast('Ditambah ke cart')}}}
function customerCard(){const pickup=ship==='pickup';return customer?`<button id="editCustomer" class="address-card"><span>${pickup?'👤':'📍'}</span><div><b>${customer.name} <small>${customer.phone_masked}</small></b><p>${pickup?'Pickup — nama dan nombor WhatsApp':customer.address_masked}</p></div><i>›</i></button>`:`<button id="openCustomer" class="address-card empty-address"><span>${pickup?'👤':'📍'}</span><div><b>${pickup?'Tambah maklumat customer':'Tambah alamat penghantaran'}</b><p>${pickup?'Nama dan nombor WhatsApp sahaja':'Nama, telefon dan alamat courier'}</p></div><i>›</i></button>`}
function review(){root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Checkout</h1></header><main class="checkout">${customerCard()}<section class="checkout-card shop-card"><h2>🏪 DecoCake.my</h2>${cart.length?cart.map((i,n)=>`<article class="checkout-item"><img class="checkout-thumb" src="${PRODUCT_IMAGES[i.k]}" alt="${i.title}"><div><b>${i.title}</b><span>${i.process}${i.review?` • ${i.review}`:''}</span><p>${i.size} • ${i.style}${i.customText?` • ${i.customText}`:''}</p><strong>${money(i.price)}</strong><div class="checkout-qty"><button data-minus="${n}">−</button><b>${i.qty}</b><button data-plus="${n}">+</button></div></div><button class="remove-item" data-r="${n}">×</button></article>`).join(''):`<p>Cart masih kosong</p>`}<label id="dateNeedRow" class="date-need-row ${date?'selected':''}"><span class="date-need-icon">📅</span><span class="date-need-copy"><b>Date <em>WAJIB</em></b><small>${date?'Tarikh dipilih':'Tekan sini untuk pilih tarikh diperlukan'}</small></span><input id="date" type="date" value="${date}" required></label></section><section class="checkout-card"><div class="section-title"><b>Shipping Option</b><span>View All ›</span></div><div class="shipping-grid">${(Object.keys(D) as Delivery[]).map(d=>`<button class="shipping-option ${ship===d?'active':''}" data-d="${d}"><div><b>${D[d].name}</b><span>${D[d].note}</span></div><strong>${D[d].price?money(D[d].price):'Free'}</strong></button>`).join('')}</div></section><section class="checkout-card"><div class="section-title"><b>Payment Methods</b></div>${ship==='pickup'?`<div class="payment-list"><button class="pay-option ${pay==='QR Pay'?'active':''}" data-p="QR Pay">▣ QR Pay <i>✓</i></button><button class="pay-option ${pay==='Cash Counter'?'active':''}" data-p="Cash Counter">▤ Cash Counter <i>✓</i></button></div>`:`<div class="payment-list"><button class="pay-option active">▣ QR Pay <i>✓</i></button></div>`}</section><section class="checkout-card payment-details"><h2>Payment Details</h2><p>Merchandise Subtotal <b>${money(sub())}</b></p><p>Shipping Subtotal <b>${money(D[ship].price)}</b></p><p class="total-line">Total Payment <b>${money(total())}</b></p></section><p class="consent">Dengan menghantar pesanan, anda bersetuju dengan <button id="terms">Terma & Notis Privasi</button>.</p></main><div class="place-bar"><div><small>Total</small><strong>${money(total())}</strong></div><button id="wa" ${cart.length?'':'disabled'}>Place Order</button></div>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('catalog');document.querySelectorAll<HTMLButtonElement>('[data-r]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.r),1);save();render()});document.querySelectorAll<HTMLButtonElement>('[data-minus]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.minus);cart[i].qty=Math.max(1,cart[i].qty-1);save();render()});document.querySelectorAll<HTMLButtonElement>('[data-plus]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.plus);cart[i].qty+=1;save();render()});document.querySelectorAll<HTMLButtonElement>('[data-d]').forEach(b=>b.onclick=()=>{ship=b.dataset.d as Delivery;if(ship!=='pickup')pay='QR Pay';render()});document.querySelectorAll<HTMLButtonElement>('[data-p]').forEach(b=>b.onclick=()=>{pay=b.dataset.p as Pay;render()});document.querySelector<HTMLInputElement>('#date')!.onchange=e=>{date=(e.target as HTMLInputElement).value;sessionStorage.setItem('need_date',date);document.querySelector<HTMLElement>('#dateNeedRow')?.classList.add('selected')};document.querySelector<HTMLButtonElement>('#openCustomer')?.addEventListener('click',customerForm);document.querySelector<HTMLButtonElement>('#editCustomer')?.addEventListener('click',customerForm);document.querySelector<HTMLButtonElement>('#terms')!.onclick=terms;document.querySelector<HTMLButtonElement>('#wa')!.onclick=submit}
function customerForm(){const pickup=ship==='pickup',c=customer||{name:'',address_line1:'',city:'',postcode:'',state:'',phone:'',phone_masked:'',address_masked:''};const addressFields=pickup?'':`<label>Alamat<input name="address_line1" required value="${c.address_line1}"></label><div><label>Bandar<input name="city" required value="${c.city}"></label><label>Poskod<input name="postcode" required value="${c.postcode}"></label></div><label>Negeri<input name="state" required value="${c.state}"></label>`;const w=modal(`<button class="modal-x">×</button><h2>${pickup?'Maklumat Customer':'Maklumat Penghantaran'}</h2><form class="address-form"><label>Nama<input name="name" required value="${c.name}"></label>${addressFields}<label>Nombor WhatsApp Malaysia<input name="phone" inputmode="tel" placeholder="Contoh: 0129554732 atau +60129554732" required value="${c.phone}"><small>Semua format akan ditukar automatik kepada +60.</small></label><button class="confirm">Save</button></form>`);w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelector<HTMLFormElement>('form')!.onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),raw={name:String(f.get('name')||''),address_line1:pickup?'':String(f.get('address_line1')||''),city:pickup?'':String(f.get('city')||''),postcode:pickup?'':String(f.get('postcode')||''),state:pickup?'':String(f.get('state')||''),phone:normalizeMalaysiaPhone(String(f.get('phone')||''))};if(!raw.phone){toast('Masukkan nombor WhatsApp Malaysia yang sah');e.currentTarget.querySelector<HTMLInputElement>('[name="phone"]')?.focus();return}const d=raw.phone.replace(/\D/g,'');customer={...raw,phone_masked:`+${d.slice(0,3)}***${d.slice(-4)}`,address_masked:pickup?'Pickup':`${raw.address_line1}, ${raw.postcode} ${raw.city}, ${raw.state}`};sessionStorage.setItem('customer',JSON.stringify(customer));localStorage.setItem('customer_profile',JSON.stringify(customer));w.remove();render()}}
function terms(){const w=modal(`<button class="modal-x">×</button><h2>Terma & Notis Privasi</h2><p>Maklumat digunakan untuk memproses tempahan dan penghantaran sahaja.</p><button class="confirm">Faham</button>`);w.querySelectorAll<HTMLButtonElement>('button').forEach(b=>b.onclick=()=>w.remove())}
function setCustomerToken(token:string){customerToken=token;localStorage.setItem('customer_token',token);const u=new URL(location.href);u.searchParams.delete('login');u.searchParams.set('c',token);history.replaceState({},'',u)}
function tabFromOrder(o:any):HistoryTab{const t=String(o.tab||'').trim();if(['to_pay','progress','receive','completed'].includes(t))return t as HistoryTab;const s=String(o.status||'').toLowerCase(),p=String(o.payment_status||'').toLowerCase();if(p.includes('unpaid')||s.includes('payment')||s.includes('pay'))return 'to_pay';if(s.includes('ship')||s.includes('receive'))return 'receive';if(s.includes('deliver')||s.includes('complete'))return 'completed';return 'progress'}
function mapDbItem(i:any):OrderItem{return {id:String(i.id||''),k:(i.product_type||'edible') as K,title:String(i.title||'Item'),qty:Number(i.qty||1),size:String(i.size||''),style:String(i.style||''),price:Number(i.price||0),workflow:String(i.workflow||'order_received'),reviewRequired:Boolean(i.review_required),customText:String(i.wording||''),previewUrl:i.design_preview_url||'',components:[]}}
function mapDbOrder(o:any,items:any[]=[]):OrderRecord{return {id:String(o.order_no||o.id),orderToken:String(o.public_token||o.id),tab:tabFromOrder(o),dateNeed:String(o.date_need||''),created:o.created_at?new Date(o.created_at).toLocaleDateString('en-GB'):'',total:Number(o.total||0),payment:String(o.payment_status||'unpaid'),delivery:String(o.delivery_method||'pickup'),deliverySummary:String(o.delivery_method||'pickup'),deliveryName:String(o.delivery_name||''),deliveryPhone:String(o.delivery_phone||''),status:String(o.status||'new'),actionCount:0,customerConfirmed:Boolean(o.customer_confirmed),canCancel:true,items:items.map(mapDbItem)}}
async function dbItems(orderId:string){const {data,error}=await supabase.from('order_items').select('*').eq('order_id',orderId);if(error)throw error;return data||[]}
async function dbOrder(token:string){let q=supabase.from('orders').select('*').eq('public_token',token).limit(1);let {data,error}=await q;if(error)throw error;if((!data||!data.length)&&/^[0-9a-f-]{36}$/i.test(token)){const r=await supabase.from('orders').select('*').eq('id',token).limit(1);data=r.data;error=r.error;if(error)throw error}if(!data||!data.length)return null;const items=await dbItems(data[0].id);return mapDbOrder(data[0],items)}
async function requestLogin(){const w=modal(`<button class="modal-x">×</button><h2>Login My Orders</h2><p>Masukkan nombor WhatsApp yang pernah digunakan semasa membuat order.</p><form class="address-form"><label>Nombor WhatsApp<input name="phone" inputmode="tel" placeholder="Contoh: 60123456789" required></label><button class="confirm">Get Login Link</button></form><small>Login link sah selama 15 minit dan hanya boleh digunakan sekali.</small>`);w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelector<HTMLFormElement>('form')!.onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,btn=form.querySelector<HTMLButtonElement>('button')!,phone=String(new FormData(form).get('phone')||'');btn.disabled=true;btn.textContent='Generating…';try{const r=await api.post('/api/login/request',{phone}),loginUrl=`${location.origin}${location.pathname}?login=${encodeURIComponent(r.data.login_token)}`,msg=`iCetak My Orders Login\n\nTekan link ini untuk buka semua order anda:\n${loginUrl}\n\nLink sah 15 minit dan sekali guna.`;w.querySelector('.modal')!.innerHTML=`<button class="modal-x">×</button><h2>Login Link Ready</h2><p>Hantar link ini ke WhatsApp sendiri, kemudian tekan link tersebut.</p><a class="confirm wa-confirm" href="https://wa.me/${r.data.phone}?text=${encodeURIComponent(msg)}" target="_blank">Open WhatsApp</a><button id="copyLogin" class="confirm secondary-confirm">Copy Login Link</button><small>Auto-send dari nombor iCetak akan disambungkan kemudian melalui WhatsApp API.</small>`;w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelector<HTMLButtonElement>('#copyLogin')!.onclick=async()=>{await navigator.clipboard.writeText(loginUrl);toast('Login link copied')}}catch{toast('Nombor tidak dijumpai');btn.disabled=false;btn.textContent='Get Login Link'}}}
function accessPage(){root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Account Access</h1></header><main class="access-page"><section class="access-card"><div class="access-icon">👤</div><h2>${customerToken?'Welcome Back':'Customer Login'}</h2><p>${customerToken?'Buka semua order yang disimpan pada akaun ini.':'Login menggunakan nombor WhatsApp yang pernah digunakan semasa membuat order.'}</p>${customerToken?'<button id="openMyOrders" class="access-primary">Open My Orders</button>':'<button id="customerMagic" class="access-primary">Login with WhatsApp</button>'}<div class="access-divider"><span>Staff iCetak</span></div><button id="staffLogin" class="access-secondary">Staff / Admin Login</button></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('catalog');document.querySelector<HTMLButtonElement>('#customerMagic')?.addEventListener('click',requestLogin);document.querySelector<HTMLButtonElement>('#openMyOrders')?.addEventListener('click',()=>{navigate('history');void loadHistory()});document.querySelector<HTMLButtonElement>('#staffLogin')!.onclick=()=>{const u=new URL(location.href);u.searchParams.set('admin','v2');location.assign(u)}}
async function loadCustomerProfile(){if(!customerToken)return;try{const {data,error}=await supabase.from('customers').select('*').eq('id',customerToken).limit(1);if(error||!data?.length)return;const c=data[0];customer={name:String(c.name||''),phone:String(c.phone||''),phone_masked:String(c.phone||''),address_line1:'',city:'',postcode:'',state:'',address_masked:'Pickup'};sessionStorage.setItem('customer',JSON.stringify(customer));localStorage.setItem('customer_profile',JSON.stringify(customer))}catch{}}
async function loadHistory(){if(!customerToken){orders=[];historyLoading=false;render();return}historyLoading=true;render();try{await loadCustomerProfile();const {data,error}=await supabase.from('orders').select('*').eq('customer_id',customerToken).order('created_at',{ascending:false}).limit(50);if(error)throw error;orders=[];for(const o of data||[])orders.push(mapDbOrder(o,await dbItems(o.id)))}catch(e){orders=[];toast('History gagal dimuatkan')}historyLoading=false;if(page==='history')render()}
async function loadOrder(token:string){orderLoading=true;render();try{const o=await dbOrder(token);if(!o)throw new Error('Order not found');currentOrder=o;selectedOrder=o.orderToken}catch{currentOrder=null;toast('Order tidak ditemui')}orderLoading=false;if(page==='order')render()}
function historyPage(){const tabs:[HistoryTab,string,string][]=[['to_pay','💳','To Pay'],['progress','🛍️','In Progress'],['receive','📦','To Receive'],['completed','✅','Completed']],shown=orders.filter(o=>o.tab===historyTab);root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>My Orders</h1></header><main class="history-page"><section class="history-hero"><h2>Track Your Order</h2><p>Semak bayaran, progress design, production dan penghantaran.</p><small>${customerToken?'Live order history':'Login diperlukan'}</small></section>${customerToken?`<nav class="history-tabs">${tabs.map(([key,icon,label])=>`<button data-tab="${key}" class="${historyTab===key?'active':''}">${icon}<span>${label}</span><b>${orders.filter(o=>o.tab===key).length}</b></button>`).join('')}</nav><section class="history-list">${historyLoading?'<div class="empty-history"><b>Loading orders…</b></div>':shown.length?shown.map(o=>`<article class="order-card" data-order="${o.orderToken}"><div class="order-card-head"><div><b>${o.id}</b><small>Order ${o.created}</small></div><span class="status-pill ${o.status==='Action Required'?'alert':''}">${o.status}</span></div><div class="order-items-mini">${o.items.map(i=>`<span>${i.qty}× ${i.title}</span>`).join('')}</div><div class="order-card-foot"><span>${o.dateNeed}</span><b>${money(o.total)}</b></div>${o.actionCount?`<em>${o.actionCount} action needed</em>`:''}</article>`).join(''):'<div class="empty-history"><b>Tiada order</b><p>Order dalam kategori ini akan muncul di sini.</p></div>'}</section>`:`<section class="empty-history"><b>Login diperlukan</b><p>Tekan Account Access untuk dapatkan link My Orders melalui WhatsApp.</p><button id="loginHistory" class="confirm">Login My Orders</button></section>`}</main><nav class="mobile-nav"><button id="navHome">⌂<span>Home</span></button><button id="navTerms">▣<span>Terms</span></button><a href="https://wa.me/${WA}" target="_blank">💬<span>Contact Us</span></a><button class="active">◷<span>History Order</span></button></nav>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('catalog');document.querySelector<HTMLButtonElement>('#navHome')!.onclick=()=>navigate('catalog');document.querySelector<HTMLButtonElement>('#navTerms')!.onclick=terms;document.querySelector<HTMLButtonElement>('#loginHistory')?.addEventListener('click',requestLogin);document.querySelectorAll<HTMLButtonElement>('[data-tab]').forEach(b=>b.onclick=()=>{historyTab=b.dataset.tab as HistoryTab;render()});document.querySelectorAll<HTMLElement>('[data-order]').forEach(e=>e.onclick=()=>{selectedOrder=e.dataset.order!;navigate('order',{orderToken:selectedOrder});void loadOrder(selectedOrder)})}
function orderPage(){if(orderLoading||!currentOrder){root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Order Detail</h1></header><main class="order-detail-page"><section class="payment-panel"><h2>${orderLoading?'Loading order…':'Order not found'}</h2></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('history');return}const o=currentOrder;root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Order Detail</h1></header><main class="order-detail-page"><section class="order-status-hero"><small>Order ID</small><h2>${o.id}</h2><p>${o.status}</p><strong>${money(o.total)}</strong></section><section class="order-detail-card"><h3>Items</h3>${o.items.map(i=>`<article class="order-detail-item"><div><b>${i.qty}× ${i.title}</b><span>${i.size} • ${i.style}</span>${i.customText?`<small>${i.customText}</small>`:''}</div><strong>${money(i.price*i.qty)}</strong></article>`).join('')}</section><section class="order-detail-card"><h3>Production Progress</h3>${o.items.flatMap(i=>i.components.length?i.components:[{id:i.id,type:i.k,label:i.title,workflow:i.workflow,reviewRequired:i.reviewRequired,reviewStatus:i.reviewRequired?'pending':'not_required',previewUrl:i.previewUrl} as ProductionComponent]).map(c=>`<div class="progress-row"><div><b>${c.label}</b><span>${c.workflow.replaceAll('_',' ')}</span></div>${c.reviewRequired?`<button data-review-url="${c.previewUrl||''}" ${c.previewUrl?'':'disabled'}>${c.previewUrl?'Review Design':'Waiting Design'}</button>`:'<small>No review required</small>'}</div>`).join('')}</section>${o.shipment?`<section class="order-detail-card shipment-card"><h3>Shipment</h3><p>${courierBadge(o.shipment.courier)} <b>${o.shipment.tracking}</b></p><p>${o.shipment.status}</p>${o.shipment.trackingLink?`<a class="confirm" href="${o.shipment.trackingLink}" target="_blank">Track Parcel</a>`:''}</section>`:''}<section class="order-detail-actions"><button id="payNow" class="confirm" ${(o.payment.toLowerCase().includes('paid')||o.status==='payment_received')?'disabled':''}>Pay / Upload Receipt</button><a class="confirm secondary-confirm" href="${orderQuestionUrl(o)}" target="_blank">Ask via WhatsApp</a></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('history');document.querySelector<HTMLButtonElement>('#payNow')?.addEventListener('click',async()=>{navigate('payment',{orderToken:o.orderToken});await loadPayment(o.orderToken)});document.querySelectorAll<HTMLButtonElement>('[data-review-url]').forEach(b=>b.onclick=()=>{const url=b.dataset.reviewUrl;if(url)window.open(url,'_blank')})}
function singleOrderUrl(token:string){const u=new URL(location.href);['c','login','confirm','page'].forEach(k=>u.searchParams.delete(k));u.searchParams.set('order',token);return u.toString()}
async function send(payload:unknown){const {data,error}=await supabase.rpc('icetak_create_order',{payload});if(error)throw new Error(error.message);return {order_id:String(data?.order_id||''),order_token:String(data?.order_token||''),customer_token:String(data?.customer_id||data?.customer_token||''),confirm_token:data?.confirm_token as string|undefined}}
async function submit(){if(!customer){customerForm();return}const normalizedPhone=normalizeMalaysiaPhone(customer.phone);if(!normalizedPhone){toast('Nombor WhatsApp Malaysia tidak sah');customerForm();return}customer.phone=normalizedPhone;if(ship!=='pickup'&&(!customer.address_line1||!customer.city||!customer.postcode||!customer.state)){toast('Lengkapkan alamat penghantaran');customerForm();return}if(!date){toast('Pilih Date dahulu');highlightDateNeed();return}const itemSummary=cart.map(i=>`<div class="review-order-item"><b>${i.qty}× ${i.title}</b><span>${i.size} • ${i.style}${i.customText?` • ${i.customText}`:''}</span><strong>${money(i.price*i.qty)}</strong></div>`).join('');const w=modal(`<button class="modal-x">×</button><h2>Review Order</h2><p>Semak semua maklumat sebelum order dihantar.</p><section class="review-order-summary"><div><span>Customer</span><b>${customer.name}</b></div><div><span>WhatsApp</span><b>${customer.phone}</b></div><div><span>Date</span><b>${date}</b></div><div><span>${ship==='pickup'?'Pickup':'Delivery'}</span><b>${ship==='pickup'?'Bandar Baru Pasir Puteh':customer.address_masked}</b></div><div><span>Courier</span><b>${D[ship].name}</b></div><div><span>Payment</span><b>${pay}</b></div>${itemSummary}<div class="review-order-total"><span>Total</span><b>${money(total())}</b></div></section><label class="whatsapp-consent"><input id="notifyWhatsapp" type="checkbox" checked><span><b>Terima notifikasi WhatsApp</b><small>Status bayaran, design, production dan penghantaran akan dihantar oleh DecoCake.my.</small></span></label><button id="confirmPlaceOrder" class="confirm">Confirm & Place Order</button><button id="backToCheckout" class="confirm secondary-confirm">Back to Edit</button><button id="cancelCheckoutReview" class="confirm secondary-confirm">Cancel Checkout</button>`);w.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>w.remove();w.querySelector<HTMLButtonElement>('#backToCheckout')!.onclick=()=>w.remove();w.querySelector<HTMLButtonElement>('#cancelCheckoutReview')!.onclick=()=>w.remove();w.querySelector<HTMLButtonElement>('#confirmPlaceOrder')!.onclick=()=>{const notifyWhatsapp=w.querySelector<HTMLInputElement>('#notifyWhatsapp')!.checked;w.remove();void createOrderNow(notifyWhatsapp)}}
async function createOrderNow(notifyWhatsapp=true){if(!customer){customerForm();return}const normalizedPhone=normalizeMalaysiaPhone(customer.phone);if(!normalizedPhone){toast('Nombor WhatsApp Malaysia tidak sah');customerForm();return}customer.phone=normalizedPhone;if(ship!=='pickup'&&(!customer.address_line1||!customer.city||!customer.postcode||!customer.state)){toast('Lengkapkan alamat penghantaran');customerForm();return}if(!date){toast('Pilih Date dahulu');highlightDateNeed();return}const btn=document.querySelector<HTMLButtonElement>('#wa')!;btn.disabled=true;btn.textContent='Creating…';try{const r=await send({customer_token:customerToken,customer,items:cart,date_need:date,delivery:ship,payment:pay,total:total(),consent:true,notify_whatsapp:notifyWhatsapp});setCustomerToken(r.customer_token);const lines=cart.map((i,n)=>`${n+1}. ${i.title}\n${i.process}\n${i.size}\n${i.style}\n${money(i.price)} × ${i.qty}`).join('\n\n');const confirmUrl=r.confirm_token?`${location.origin}${location.pathname}?confirm=${encodeURIComponent(r.confirm_token)}`:'',msg=r.confirm_token?`Hi ${customer.name}, sila semak dan sahkan order iCetak anda.\n\nOrder ID: ${r.order_id}\nDate: ${date}\nJumlah: ${money(total())}\nBayaran: Cash semasa pickup\n\nTekan link ini untuk sahkan order:\n${confirmUrl}\n\nOrder hanya masuk production selepas disahkan.`:`Hi iCetak, saya ingin membuat tempahan.\n\nOrder ID: ${r.order_id}\nDate: ${date}\n\n${lines}\n\nBayaran\n${pay}\n\nJumlah\n${money(total())}`;const waUrl=r.confirm_token?`https://wa.me/${customer.phone.replace(/\D/g,'')}?text=${encodeURIComponent(msg)}`:`https://wa.me/${WA}?text=${encodeURIComponent(msg)}`;cart=[];save();date='';sessionStorage.removeItem('need_date');const confirmation=modal(`<button class="modal-x">×</button><h2>Order Created</h2><p>Order ID</p><strong class="order-confirm-id">${r.order_id}</strong><p>${r.confirm_token?'Order disimpan tetapi dikunci. Customer mesti confirm sebelum masuk production.':pay==='QR Pay'?'Order disimpan dalam To Pay sehingga bayaran disahkan.':'Order berjaya disimpan.'}</p>${r.confirm_token?`<a class="confirm wa-confirm" href="${waUrl}" target="_blank">Send Confirmation on WhatsApp</a><a class="confirm secondary-confirm" href="${confirmUrl}">Confirm Order Now</a>`:`<button id="payCreatedOrder" class="confirm wa-confirm">Pay Now</button>`}<button id="copyCreatedLink" class="confirm secondary-confirm">Copy Tracking Link</button><button id="viewCreated" class="confirm">View Order</button>`);confirmation.querySelector<HTMLButtonElement>('.modal-x')!.onclick=()=>confirmation.remove();confirmation.querySelector<HTMLButtonElement>('#payCreatedOrder')?.addEventListener('click',()=>{confirmation.remove();selectedOrder=r.order_token;navigate('payment',{orderToken:selectedOrder});void loadPayment(selectedOrder)});confirmation.querySelector<HTMLButtonElement>('#copyCreatedLink')!.onclick=async()=>{await navigator.clipboard.writeText(singleOrderUrl(r.order_token));toast('Tracking link copied')};confirmation.querySelector<HTMLButtonElement>('#viewCreated')!.onclick=()=>{confirmation.remove();selectedOrder=r.order_token;currentOrder=null;navigate('order',{orderToken:selectedOrder});void loadOrder(selectedOrder)}}catch{toast('Order gagal disimpan');btn.disabled=false;btn.textContent='Place Order'}}
function ensurePaymentConnection(){if(paymentConnection)return paymentConnection;const conn=ws.connect();conn.onMessage(message=>{const payload=message?.payload;if(message?.type!=='entity.update'||payload?.entity_type!=='payment'||payload.entity_id!==paymentSubscriptionToken)return;const next=payload.data?.payment as PaymentInfo|undefined;if(!next)return;const firstMatch=paymentInfo?.status!=='matched'&&next.status==='matched';paymentInfo=next;if(page==='payment'){render();if(firstMatch)toast('Payment received ✅')}});paymentConnection=conn;return conn}
async function subscribePayment(token:string){const conn=ensurePaymentConnection();await conn.ready;if(!conn.connectionId)return;if(paymentSubscriptionToken&&paymentSubscriptionToken!==token)await api.post('/api/subscriptions/remove',{entity_type:'payment',entity_id:paymentSubscriptionToken,connection_id:conn.connectionId}).catch(()=>{});paymentSubscriptionToken=token;await api.post('/api/subscriptions',{entity_type:'payment',entity_id:token,connection_id:conn.connectionId})}
async function unsubscribePayment(){clearInterval(paymentPollTimer);clearInterval(paymentTimer);const conn=paymentConnection,token=paymentSubscriptionToken;paymentSubscriptionToken='';if(conn?.connectionId&&token)await api.post('/api/subscriptions/remove',{entity_type:'payment',entity_id:token,connection_id:conn.connectionId}).catch(()=>{})}
async function loadPayment(token:string){paymentLoading=true;paymentInfo=null;page='payment';render();try{const o=await dbOrder(token);if(!o)throw new Error('Order not found');const alreadyPaid=o.payment.toLowerCase().includes('paid')||o.status==='payment_received';try{const pr=await api.post(`/api/orders/${encodeURIComponent(token)}/payment-session`,{force_new:false});const pdata=(pr.data as any)?.payment;if(pdata){paymentInfo={id:String(pdata.id||token),orderToken:token,orderId:o.id,baseAmount:Number(pdata.base_amount||o.total),expectedAmount:Number(pdata.expected_amount||o.total),discount:Number(pdata.discount||0),expiresAt:pdata.expires_at?new Date(pdata.expires_at).getTime():Date.now()+10*60*1000,status:String(pdata.status||'pending'),transactionId:String(pdata.transaction_id||''),receiptName:String(pdata.receipt_name||''),receiptUrl:String(pdata.receipt_url||''),submittedAt:pdata.submitted_at?new Date(pdata.submitted_at).getTime():0,matchedAt:pdata.matched_at?new Date(pdata.matched_at).getTime():0};if(alreadyPaid)paymentInfo.status='matched'}}catch{paymentInfo={id:token,orderToken:token,orderId:o.id,baseAmount:o.total,expectedAmount:o.total,discount:0,expiresAt:Date.now()+10*60*1000,status:alreadyPaid?'matched':'pending',transactionId:'',receiptName:'',receiptUrl:'',submittedAt:0,matchedAt:0}}}catch{toast('Payment page gagal dimuatkan')}paymentLoading=false;render()}
function receiptBase64(file:File){return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').split(',')[1]||'');reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})}
function paymentPage(){clearInterval(paymentTimer);clearInterval(paymentPollTimer);if(paymentLoading||!paymentInfo){root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Payment</h1></header><main class="payment-page"><section class="payment-panel"><h2>${paymentLoading?'Preparing secure amount…':'Payment unavailable'}</h2></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('order');return}const p=paymentInfo;if(p.status==='matched'){root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Payment</h1></header><main class="payment-page"><section class="payment-panel payment-success-hero"><div class="payment-success-icon">✓</div><h2>Payment Received</h2><strong>${money(p.expectedAmount)}</strong><p>Bayaran telah dipadankan secara automatik. Order anda sudah masuk ke proses seterusnya.</p><button id="viewPaidOrder" class="pay-now-btn">View Order Status</button></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>{void unsubscribePayment();goBack('order')};document.querySelector<HTMLButtonElement>('#viewPaidOrder')!.onclick=()=>{void unsubscribePayment();selectedOrder=p.orderToken;navigate('order',{orderToken:p.orderToken});void loadOrder(p.orderToken)};return}const remaining=Math.max(0,p.expiresAt-Date.now()),minutes=String(Math.floor(remaining/60000)).padStart(2,'0'),seconds=String(Math.floor((remaining%60000)/1000)).padStart(2,'0'),expired=remaining<=0;root.innerHTML=`<header class="checkout-head"><button id="back">‹</button><h1>Pay Order</h1></header><main class="payment-page"><section class="payment-panel payment-hero"><small>Order ${p.orderId}</small><h2>Scan DuitNow QR</h2><div class="payment-countdown ${expired?'expired':''}"><span>${expired?'Session expired':'Amount reserved for'}</span><b id="paymentCountdown">${minutes}:${seconds}</b></div><div class="payment-live"><i></i> Live payment detection active</div><img class="payment-qr" src="https://t3747262.p.clickup-attachments.com/t3747262/836016e0-e613-447b-b61a-291fddd3f83d_large.png" alt="DecoCake.my DuitNow QR"><p>Masukkan jumlah ini tepat semasa membuat bayaran:</p><button id="copyPaymentAmount" class="payment-amount"><small>Exact Amount</small><strong>${money(p.expectedAmount)}</strong><span>Tap to copy</span></button>${p.discount>0?`<div class="payment-discount">Discount matching amount: ${money(p.discount)}</div>`:''}<small>Jangan round up atau ubah sen. Sistem padankan bayaran berdasarkan jumlah ini.</small>${expired?'<button id="refreshPaymentSession" class="pay-now-btn">Generate New 10-Minute Amount</button>':''}</section><section class="payment-panel"><h3>Bukti Bayaran</h3><p>Selepas bayar, snap atau upload resit JPG, PNG atau PDF.</p>${p.status==='matched'?`<div class="payment-approved"><b>✅ Payment Confirmed</b><span>Bayaran telah disahkan dan order sedang diproses.</span>${p.receiptUrl?`<a href="${p.receiptUrl}" target="_blank">View receipt</a>`:''}</div>`:p.receiptUrl?`<div class="payment-pending"><b>⏳ Pending Admin Approval</b><span>Bukti bayaran telah diterima. Admin sedang menyemak bayaran anda.</span><a class="receipt-ready" href="${p.receiptUrl}" target="_blank">View uploaded receipt</a><small>Tak perlu upload semula. Status akan berubah selepas admin mengesahkan bayaran.</small></div>`:`<label class="receipt-upload">Choose Receipt<input id="receiptFile" type="file" accept="image/jpeg,image/png,application/pdf"></label><button id="uploadReceipt" class="pay-now-btn">Upload Payment Receipt</button>`}</section><section class="payment-panel gateway-later"><h3>Payment Gateway</h3><p>Online payment link akan ditambah kemudian.</p><button disabled>Coming Soon</button></section></main>`;document.querySelector<HTMLButtonElement>('#back')!.onclick=()=>goBack('order');document.querySelector<HTMLButtonElement>('#copyPaymentAmount')!.onclick=async()=>{await navigator.clipboard.writeText(p.expectedAmount.toFixed(2));toast('Amount copied')};document.querySelector<HTMLButtonElement>('#refreshPaymentSession')?.addEventListener('click',()=>void loadPayment(selectedOrder));document.querySelector<HTMLButtonElement>('#uploadReceipt')?.addEventListener('click',async()=>{const input=document.querySelector<HTMLInputElement>('#receiptFile')!,file=input.files?.[0];if(!file){toast('Pilih receipt dahulu');return}if(file.size>5*1024*1024){toast('Receipt maksimum 5MB');return}const button=document.querySelector<HTMLButtonElement>('#uploadReceipt')!;button.disabled=true;button.textContent='Uploading…';try{const data=await receiptBase64(file),r=await api.post('/api/orders/'+encodeURIComponent(selectedOrder)+'/payment-receipt',{data,mime_type:file.type,file_name:file.name});paymentInfo=r.data.payment;toast('Receipt uploaded');render()}catch{toast('Upload receipt gagal');button.disabled=false;button.textContent='Upload Payment Receipt'}});if(!expired)paymentTimer=window.setInterval(()=>{if(page!=='payment'){clearInterval(paymentTimer);return}const left=Math.max(0,p.expiresAt-Date.now()),el=document.querySelector<HTMLElement>('#paymentCountdown');if(el)el.textContent=`${String(Math.floor(left/60000)).padStart(2,'0')}:${String(Math.floor((left%60000)/1000)).padStart(2,'0')}`;if(left<=0){clearInterval(paymentTimer);render()}},1000);paymentPollTimer=window.setInterval(async()=>{if(page!=='payment'||!paymentInfo||paymentInfo.status==='matched'){clearInterval(paymentPollTimer);return}const tok=paymentInfo.orderToken;const {data}=await supabase.from('orders').select('payment_status,status').or(`public_token.eq.${tok},order_no.eq.${tok}`).limit(1);if(data&&data[0]&&(String(data[0].payment_status).toLowerCase().includes('paid')||String(data[0].status).toLowerCase()==='payment_received')){clearInterval(paymentPollTimer);clearInterval(paymentTimer);paymentInfo={...paymentInfo,status:'matched'};if(page==='payment'){render();toast('Payment received ✅')}}},3000)}
async function loadConfirmation(token:string){confirmationLoading=true;page='confirm';render();try{const r=await api.get('/api/order-confirmations/'+encodeURIComponent(token));confirmationOrder=r.data.order as OrderRecord}catch{confirmationOrder=null}confirmationLoading=false;render()}
function confirmPage(){if(confirmationLoading){root.innerHTML='<main class="confirm-page"><section class="confirm-card"><h2>Loading order…</h2></section></main>';return}if(!confirmationOrder){root.innerHTML='<main class="confirm-page"><section class="confirm-card"><h2>Link tidak sah</h2><p>Confirmation link tidak dijumpai atau sudah tamat.</p></section></main>';return}const o=confirmationOrder;root.innerHTML=`<main class="confirm-page"><section class="confirm-card"><div class="confirm-icon">✓</div><small>iCetak Order Confirmation</small><h1>${o.id}</h1><p>Date: <b>${o.dateNeed}</b></p><div class="confirm-items">${o.items.map(i=>`<span>${i.qty}× ${i.title} — ${money(i.price*i.qty)}</span>`).join('')}</div><strong class="confirm-total">${money(o.total)}</strong>${o.customerConfirmed?'<div class="confirmed-banner">✅ Order ini sudah disahkan.</div>':'<><p>Dengan menekan butang di bawah, customer mengesahkan detail order betul dan iCetak boleh mula proses production.</p><button id="confirmCashOrder" class="confirm">Ya, Order Betul — Confirm</button></>'}</section></main>`;document.querySelector<HTMLButtonElement>('#confirmCashOrder')?.addEventListener('click',async()=>{const b=document.querySelector<HTMLButtonElement>('#confirmCashOrder')!;b.disabled=true;b.textContent='Confirming…';try{await api.post('/api/order-confirmations/'+encodeURIComponent(confirmationToken),{});toast('Order confirmed');await loadConfirmation(confirmationToken)}catch{toast('Confirmation gagal');b.disabled=false;b.textContent='Ya, Order Betul — Confirm'}})}
function render(){page==='catalog'?catalog():page==='detail'?detail():page==='review'?review():page==='history'?historyPage():page==='payment'?paymentPage():page==='access'?accessPage():page==='confirm'?confirmPage():orderPage()}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event as InstallPromptEvent;if(page==='catalog')render()});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;isStandalone=true;toast('DecoCake.my installed')});window.addEventListener('popstate',event=>{const state=event.state as {page?:Page;product?:K;orderToken?:string}|null;if(!state?.page){if(page==='payment')void unsubscribePayment();page='catalog';render();return}if(page==='payment'&&state.page!=='payment')void unsubscribePayment();page=state.page;if(state.product)product=state.product;if(state.orderToken){selectedOrder=state.orderToken;if(page==='order'){currentOrder=null;void loadOrder(selectedOrder);return}}render()});if('serviceWorker' in navigator)window.addEventListener('load',()=>{void navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>navigator.serviceWorker.register('./sw.js'))});
async function bootstrap(){history.replaceState({page,product,orderToken:selectedOrder},'',location.href);if(customerToken)await loadCustomerProfile();const params=new URLSearchParams(location.search),orderToken=params.get('order'),confirmToken=params.get('confirm');if(orderToken){selectedOrder=orderToken;if(params.get('page')==='payment'){page='payment';history.replaceState({page,product,orderToken:selectedOrder},'',location.href);await loadPayment(orderToken);return}page='order';currentOrder=null;await loadOrder(orderToken);return}if(confirmToken){confirmationToken=confirmToken;await loadConfirmation(confirmToken);return}const loginToken=params.get('login');if(loginToken){root.innerHTML='<main class="history-page"><div class="empty-history"><b>Signing in…</b><p>Checking temporary WhatsApp login link.</p></div></main>';try{const r=await api.post('/api/login/exchange',{login_token:loginToken});setCustomerToken(r.data.customer_token);page='history';await loadHistory();return}catch{const u=new URL(location.href);u.searchParams.delete('login');history.replaceState({},'',u);toast('Login link tidak sah atau telah tamat tempoh')}}render()}
